// Normalizar y validar TaskPayload<ExtractorInput>
const input = $input.first().json;

if (!input.taskId || !input.inputData || !input.inputData.rawContractText) {
  throw new Error('Payload inválido: taskId e inputData.rawContractText son mandatorios.');
}

const rawText = input.inputData.rawContractText;
const targetClauses = input.inputData.targetClauses || [
  'INDEMNIFICATION',
  'LIMITATION_OF_LIABILITY',
  'JURISDICTION_AND_GOVERNING_LAW',
  'TERMINATION'
];

return [{
  json: {
    taskId: input.taskId,
    auditId: input.auditId,
    rawContractText: rawText,
    targetClauses: targetClauses,
    timestamp: new Date().toISOString()
  }
}];

